test_vcfux_unsigned_edges:
  #_ REGISTER_IN v3 [00000000, 00000001, 7FFFFFFF, 80000000]
  vcfux v4, v3, 0
  blr
  #_ REGISTER_OUT v3 [00000000, 00000001, 7FFFFFFF, 80000000]
  #_ REGISTER_OUT v4 [00000000, 3F800000, 4F000000, 4F000000]

test_vcfux_unsigned_max:
  #_ REGISTER_IN v3 [FFFFFFFF, FFFFFFFE, 00FFFFFF, 01000000]
  vcfux v4, v3, 0
  blr
  #_ REGISTER_OUT v3 [FFFFFFFF, FFFFFFFE, 00FFFFFF, 01000000]
  #_ REGISTER_OUT v4 [4F800000, 4F800000, 4B7FFFFF, 4B800000]

test_vcfux_scale:
  #_ REGISTER_IN v3 [80000000, 40000000, 00000400, 00000001]
  vcfux v4, v3, 10
  blr
  #_ REGISTER_OUT v3 [80000000, 40000000, 00000400, 00000001]
  #_ REGISTER_OUT v4 [4A000000, 49800000, 3F800000, 3A800000]
